import type { API, FileInfo, ObjectProperty, Property } from "jscodeshift"
import { getStringValue } from "../ast-helpers"

export const name = path.basename(__filename, path.extname(__filename))
export const description =
    "remove redundant `driver: require(\"expo-sqlite\")` from Expo DataSource options"

// True only for a plain `require("expo-sqlite")` call expression — not a member
// access like `require("expo-sqlite").default`, an identifier/variable, or a
// call to some other package.
const isRequireExpoSqlite = (node: {
    type: string
    callee?: { type: string; name?: string }
    arguments?: unknown[]
}): boolean => {
    if (node.type !== "CallExpression") return false
    if (node.callee?.type !== "Identifier" || node.callee.name !== "require") {
        return false
    }
    const args = node.arguments ?? []
    if (args.length !== 1) return false
    return getStringValue(args[0] as never) === "expo-sqlite"
}

export const datasourceExpo = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    let hasChanges = false

    // Scope to ObjectExpressions that look like TypeORM Expo DataSource options:
    // they carry both `type: "expo"` and a sibling `database` property. This
    // avoids touching unrelated `{ type: "expo" }` objects. Accept both
    // identifier (`type:`) and string-literal (`"type":`) keys.
    root.find(j.ObjectExpression).forEach((objPath) => {
        let isExpo = false
        let hasDatabase = false
        let driverProp: ObjectProperty | Property | null = null

        for (const prop of objPath.node.properties) {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                continue
            }

            const keyName =
                prop.key.type === "Identifier"
                    ? prop.key.name
                    : getStringValue(prop.key)

            if (keyName === "type" && getStringValue(prop.value) === "expo") {
                isExpo = true
            } else if (keyName === "database") {
                hasDatabase = true
            } else if (keyName === "driver") {
                driverProp = prop
            }
        }

        if (!isExpo || !hasDatabase || !driverProp) return

        if (!isRequireExpoSqlite(driverProp.value as never)) return

        objPath.node.properties = objPath.node.properties.filter(
            (prop) => prop !== driverProp,
        )
        hasChanges = true
    })

    return hasChanges ? root.toSource() : undefined
}

export const fn = datasourceExpo
export default fn
